  const currentPrice = document.querySelector('[data-testid="current-price"], [class*="current-price"], [class*="special-price"], [class*="price-sales"]')?.innerText?.trim();
  const allPrices = Array.from(document.querySelectorAll('*')).filter(el => el.children.length === 0 && /\$\d+(\.\d{2})?/.test(el.innerText)).map(el => el.innerText.trim());

  // Check size 12 button specifically
  const size12Btn = Array.from(document.querySelectorAll('button, [role="radio"], [data-testid*="size"]')).find(el => el.innerText.trim() === '12');
  const size12Aria = size12Btn ? {
    ariaDisabled: size12Btn.getAttribute('aria-disabled'),
    disabled: size12Btn.disabled,
    classes: size12Btn.className,
    text: size12Btn.innerText
  } : null;

  return {
    h1,
    currentPrice,
    allPrices: allPrices.slice(0, 10),
    size12Aria
  };
});
