await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });

// Fetch the list of product links
const productUrls = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/product/"]')).map(a => a.href);
  return [...new Set(links)];
});

console.log("Total unique product links:", productUrls.length);

// Let's check the descriptions of these products
const matching = [];
for (let i = 0; i < Math.min(productUrls.length, 12); i++) {
  const url = productUrls[i];
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 6000 });
  const data = await browserjs(tabId, () => {
    const text = document.body.innerText;
    const title = document.querySelector('h1')?.innerText?.trim();
    const price = document.querySelector('[class*="price-box"], [class*="price"]')?.innerText?.trim() || text.match(/US\$\s*\d+/)?.[0];
    const desc = document.querySelector('[class*="description"], [class*="intro"], p')?.innerText?.trim();
    const hasVNeck = text.toLowerCase().includes('v-neck') || text.toLowerCase().includes('deep v');
    const hasDeepV = text.toLowerCase().includes('deep v') || text.toLowerCase().includes('plunging');
    return { title, price, hasVNeck, hasDeepV, textSnippet: text.slice(1000, 2500) };
  });
  console.log(`[${i}] ${url.split('/').pop()}: Title="${data.title}", Price="${data.price}", VNeck=${data.hasVNeck}, DeepV=${data.hasDeepV}`);
  if (data.hasDeepV || (data.hasVNeck && data.textSnippet.toLowerCase().includes('v-neck'))) {
    matching.push({ url, ...data });
  }
}

console.log("Matching dresses:", matching.map(m => ({ title: m.title, price: m.price, url: m.url })));

