await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });

// Extract title, price, leather details, and color/material/design options
const bootDetails = await browserjs(tabId, () => {
  const h1 = document.querySelector('h1')?.innerText?.trim();
  const price = document.querySelector('[data-price], [class*="price"], [class*="Price"]')?.innerText?.trim() || document.body.innerText.match(/\$\d+/)?.[0];

  // Find color swatches or options
  const colorButtons = Array.from(document.querySelectorAll('[data-swatch-name], [aria-label*="Select"], button[class*="swatch"], [class*="color-option"], [data-color]')).map(el => {
    return el.getAttribute('data-swatch-name') || el.getAttribute('aria-label') || el.getAttribute('data-color') || el.innerText?.trim();
  }).filter(Boolean);

  // Also check all inputs or labels for color
  const radioLabels = Array.from(document.querySelectorAll('input[name*="color"] + label, input[name*="Color"] + label, [class*="ColorSwatch"]')).map(el => el.innerText?.trim() || el.getAttribute('aria-label')).filter(Boolean);

  // Get description/materials
  const desc = document.querySelector('[class*="description"], [data-accordion-content]')?.innerText || document.body.innerText.match(/leather[^\n]+/gi);

  return {
    h1,
    price,
    colorButtons: [...new Set(colorButtons)],
    radioLabels: [...new Set(radioLabels)],
    desc
  };
});

